<script setup>definePageMeta({layout:'therapist'});const {data:orders}=await useOrders();const history=computed(()=>orders.value.filter(o=>!o.assignment?.isActive||['COMPLETED','PAID','CLOSED','CANCELLED_BY_ADMIN','CANCELLED_BY_CUSTOMER'].includes(o.orderStatus)))</script><template><div><LayoutPageHeader title="Histori job" description="Riwayat pelayanan, penolakan, dan pengalihan job Anda." /><OrderJobCard v-for="o in history" :key="o.id" :order="o" /><UiEmptyState v-if="!history.length" title="Belum ada histori" /></div></template>